uint64_t sample_mask;
array<uint64_t,N+G> wire_values(const Program&p,int forced=-1,uint64_t replacement=0){array<uint64_t,N+G>v;for(int i=0;i<R;i++)v[i]=raw_inputs[i];int at=R;for(int i=0;i<8;i++)for(auto[a,b]:free_variants[i][p.choice[i]])v[at++]=v[a]|v[b];assert(at==N);for(int i=0;i<G;i++){auto t=p.g[i];v[N+i]=(i==forced)?replacement:(t.op?(v[t.a]|v[t.b]):(v[t.a]&v[t.b]));}return v;}
Program guided_repair(const Program&p,const Evaluation&e,mt19937_64&rng,bool two){array<bool,G>raw{};vector<int>active;auto visit=[&](auto&&self,int w)->void{if(w<N||raw[w-N])return;int i=w-N;raw[i]=true;self(self,p.g[i].a);self(self,p.g[i].b);active.push_back(i);};visit(visit,p.out);if(active.empty())return p;int i=active[rng()%active.size()],j=-1;if(two){vector<int>spare;for(int k=0;k<i;k++)if(!raw[k])spare.push_back(k);if(spare.empty())return p;j=(rng()%4)?spare.back():spare[rng()%spare.size()];}
 auto v=wire_values(p),low_values=wire_values(p,i,0),high_values=wire_values(p,i,sample_mask);uint64_t low=low_values[p.out],care=low^high_values[p.out];if(!care)return p;int limit=N+(two?j:i);vector<int>prefix;for(int a=0;a<limit;a++)if(e.rep[a]==a)prefix.push_back(a);struct Candidate{Gate first,second;};vector<Candidate>choices;int besterr=e.err,seen=0;
 auto consider=[&](Candidate c,uint64_t value){int error=__builtin_popcountll((low|(value&care))^target);if(error>besterr)return;if(error<besterr){besterr=error;choices.clear();seen=0;}seen++;if(choices.size()<48)choices.push_back(c);else{int pick=rng()%seen;if(pick<48)choices[pick]=c;}};
 for(int a:prefix)for(int b:prefix)if(a<=b)for(int op=0;op<2;op++){uint64_t value=op?(v[a]|v[b]):(v[a]&v[b]);if(!two)consider({{op,a,b},{0,0,0}},value);else for(int c:prefix)for(int last=0;last<2;last++)consider({{op,a,b},{last,N+j,c}},last?(value|v[c]):(value&v[c]));}
 auto energy=[](const Evaluation&z){return 2.0*z.err+20.0*max(0,z.cost-TARGET)+0.002*z.cost+(z.bad?0:0.4);};Program best=p;double bestscore=energy(e);int ties=1;for(auto c:choices){Program q=p;if(two){q.g[j]=c.first;q.g[i]=c.second;}else q.g[i]=c.first;Evaluation f=evaluate(q);double score=energy(f);if(score<bestscore){bestscore=score;best=q;ties=1;}else if(score==bestscore&&rng()%++ties==0)best=q;}return best;}
